// Golden values are generated by the existing Node protocol, not the Kotlin port.
import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { portableValue } from '../../mobile-sync/workspaceProtocol.js';

const root = new URL('../../', import.meta.url);
const fixture = JSON.parse(await readFile(new URL('mobile-sync/fixtures/workspace.json', root), 'utf8'));
const rows = fixture.records.map(record => ({ kind: record.kind, input: record.versions[0].value }));
rows.push(
  { kind: 'agent', input: { name: null, identity: 'fixture', model: null } },
  { kind: 'project', input: { name: 'project', knowledgeIds: ['b', 'a', 'a'], agentOverrides: { main: { name: 'role' } } } },
  { kind: 'knowledge', input: { title: null, content: 'text', projectId: 'invalid/id' } },
  { kind: 'conversation', input: { agentId: null, knowledgeIds: ['b', 'a'], model: { name: 'API', baseURL: 'https://example.com/v1' } } },
  { kind: 'memory', input: { id: 'fact', memoryID: 'memory', chatId: 'chat', agentId: 'main', scope: 'chat', status: 'active', text: 'remember', updatedAt: '2026-10-14T00:00:00Z', validTo: null } },
  { kind: 'message', input: { chatId: 'chat', models: [{ requestedModel: 'fixture', simulated: true }], scene: { runId: 'run', status: 'completed', operations: [{ module: 'compute', status: 'completed' }], sources: [{ url: 'https://example.com/doc', cited: true }] } } },
);
const golden = rows.map(row => ({ ...row, expected: portableValue(row.kind, row.input) }));
const destination = new URL('android/app/src/test/resources/portable-records.json', root);
await mkdir(new URL('.', destination), { recursive: true });
await writeFile(destination, JSON.stringify(golden, null, 2) + '\n');
console.log(`${golden.length} Node golden records -> ${fileURLToPath(destination)}`);
